import React, { useState } from 'react';

function LoginPage({ role, onBack, onLogin }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      // Make sure backend is running on port 5000
      const response = await fetch('http://localhost:5000/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password, role })
      });

      const data = await response.json();

      if (response.ok) {
        // Save token and user data
        localStorage.setItem('token', data.token);
        localStorage.setItem('user', JSON.stringify(data.user));
        onLogin(data.user);
      } else {
        setError(data.error || 'Login failed. Please check your credentials.');
      }
    } catch (err) {
      console.error('Login error:', err);
      setError('Cannot connect to server. Make sure backend is running on port 5000');
    } finally {
      setLoading(false);
    }
  };

  const roleIcons = {
    customer: '👤',
    provider: '🔧',
    driver: '🚗',
    admin: '👑'
  };

  const roleTitles = {
    customer: 'Customer Login',
    provider: 'Provider Login',
    driver: 'Driver Login',
    admin: 'Admin Login'
  };

  const rolePlaceholders = {
    customer: 'customer@example.com',
    provider: 'provider@example.com',
    driver: 'driver@example.com',
    admin: 'admin@carcareconnect.com'
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <button onClick={onBack} style={styles.backButton}>← Back</button>

        <div style={styles.logoSection}>
          <span style={styles.logoIcon}>🚗💨</span>
          <h2 style={styles.brandName}>Car Care Connect</h2>
        </div>

        <div style={styles.roleIcon}>{roleIcons[role]}</div>
        <h2 style={styles.title}>{roleTitles[role]}</h2>

        {error && <div style={styles.error}>{error}</div>}

        <form onSubmit={handleSubmit}>
          <input
            type="email"
            placeholder={rolePlaceholders[role]}
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={styles.input}
            required
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={styles.input}
            required
          />
          <button type="submit" style={styles.button} disabled={loading}>
            {loading ? 'Logging in...' : `Login as ${role.charAt(0).toUpperCase() + role.slice(1)}`}
          </button>
        </form>

        <p style={styles.demoCredentials}>
          <strong>Demo Credentials:</strong><br/>
          Email: customer@carcareconnect.com<br/>
          Password: password123
        </p>

        <p style={styles.registerLink}>
          New to Car Care Connect?{' '}
          <a href="#" onClick={(e) => { e.preventDefault(); alert('Registration coming soon! Use demo credentials above.'); }}>
            Create an account
          </a>
        </p>
      </div>
    </div>
  );
}

const styles = {
  container: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    minHeight: '80vh',
    backgroundColor: '#f9fafb'
  },
  card: {
    backgroundColor: 'white',
    padding: '40px',
    borderRadius: '12px',
    boxShadow: '0 4px 6px rgba(0,0,0,0.1)',
    width: '100%',
    maxWidth: '400px',
    position: 'relative'
  },
  backButton: {
    position: 'absolute',
    top: '20px',
    left: '20px',
    background: 'none',
    border: 'none',
    cursor: 'pointer',
    color: '#6b7280',
    fontSize: '14px'
  },
  logoSection: {
    textAlign: 'center',
    marginBottom: '20px'
  },
  logoIcon: {
    fontSize: '32px',
    display: 'block'
  },
  brandName: {
    fontSize: '16px',
    color: '#6b7280',
    marginTop: '5px'
  },
  roleIcon: {
    fontSize: '48px',
    textAlign: 'center',
    marginBottom: '15px'
  },
  title: {
    textAlign: 'center',
    marginBottom: '25px',
    color: '#1f2937',
    fontSize: '1.5rem'
  },
  input: {
    width: '100%',
    padding: '12px',
    marginBottom: '16px',
    border: '1px solid #d1d5db',
    borderRadius: '8px',
    fontSize: '16px',
    boxSizing: 'border-box'
  },
  button: {
    width: '100%',
    padding: '12px',
    backgroundColor: '#2563eb',
    color: 'white',
    border: 'none',
    borderRadius: '8px',
    fontSize: '16px',
    cursor: 'pointer',
    fontWeight: 'bold'
  },
  error: {
    backgroundColor: '#fee2e2',
    color: '#dc2626',
    padding: '10px',
    borderRadius: '6px',
    marginBottom: '20px',
    textAlign: 'center',
    fontSize: '14px'
  },
  demoCredentials: {
    textAlign: 'center',
    marginTop: '20px',
    padding: '10px',
    backgroundColor: '#f3f4f6',
    borderRadius: '6px',
    fontSize: '12px',
    color: '#6b7280'
  },
  registerLink: {
    textAlign: 'center',
    marginTop: '20px',
    color: '#6b7280',
    fontSize: '14px'
  }
};

export default LoginPage;
